-- =====================================================================
-- TÉCNICA · PTAR (Code C) · CARGA INICIAL DEL MAPA DE LA PTAR EL SALGUERO (generado por carga/generar_carga.py; no se edita a mano).
-- GeoJSON: ptar_el_salguero_osm.geojson · md5 6cfd0a245b3fc12752a2663db432dfba · 39 elementos del dibujo (laguna 31, perimetro 1, punto_medicion 4, tramo 3).
-- Más la copia D12: los activos vigentes de redes (alc_pozos, alc_conductos, alc_descargas) que tocan el perímetro PTAR-PER, sin retirados ni ocultos y sin los que ya están en el dibujo.
-- redes NO se toca (solo se lee redes.v_activo_vigente). Nada se borra. Va DESPUÉS de la migración de PTAR-1. Una transacción: si algo no calza, no queda nada.
-- =====================================================================
begin;
do $$
begin
  if to_regclass('tecnica.elementos_planta') is null then raise exception 'CARGA PTAR: falta la migración de PTAR-1 (tecnica.elementos_planta)'; end if;
  if not exists (select 1 from tecnica.instalaciones where codigo = 'ptar' and activa) then raise exception 'CARGA PTAR: falta la instalación ptar'; end if;
  if exists (select 1 from tecnica.elementos_planta e join tecnica.instalaciones i on i.id = e.instalacion_id where i.codigo = 'ptar' and e.activo) then
    raise exception 'CARGA PTAR: la PTAR ya tiene elementos activos: esta carga es solo la inicial (para corregir, desactive con motivo y cree la fila nueva, D9)';
  end if;
  if (select count(*) from tecnica.puntos where codigo in ('PTAR-AFL', 'PTAR-EFL', 'PTAR-RIO-ABJ', 'PTAR-RIO-ARR') and tipo = 'ptar' and activo) <> 4 then
    raise exception 'CARGA PTAR: faltan los puntos de la PTAR (PTAR-AFL, PTAR-EFL, PTAR-RIO-ABJ, PTAR-RIO-ARR): aplique antes PTAR-3 (tecnica_ptar_control)';
  end if;
end $$;
create temp table _inst on commit drop as select id from tecnica.instalaciones where codigo = 'ptar';

